import * as THREE from 'three';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

// Create the scene
const root = createScene();

// OBJ file writer
class OBJExporter {
  constructor() {
    this.vertexIndex = 1;
    this.output = '';
    this.currentGroup = '';
  }

  // Apply -90 degree X-rotation for Blender Z-up
  rotateForBlender(vector) {
    // Three.js uses Y-up, Blender uses Z-up
    // Rotate -90 degrees around X-axis: (x, y, z) -> (x, z, -y)
    const x = vector.x;
    const y = vector.y;
    const z = vector.z;
    return new THREE.Vector3(x, z, -y);
  }

  // Transform vertex with world matrix
  transformVertex(vertex, matrix) {
    return vertex.clone().applyMatrix4(matrix);
  }

  // Transform normal
  transformNormal(normal, matrix) {
    const normalMatrix = new THREE.Matrix3().getNormalMatrix(matrix);
    return normal.clone().applyMatrix3(normalMatrix).normalize();
  }

  exportObject(object) {
    const meshes = [];

    // Collect all meshes with their world transforms
    object.traverse((child) => {
      if (child.isMesh && child.geometry) {
        meshes.push({
          mesh: child,
          worldMatrix: child.matrixWorld.clone()
        });
      }
    });

    let vertexOffset = 0;

    meshes.forEach(({ mesh, worldMatrix }) => {
      const geometry = mesh.geometry;

      // Skip if no geometry
      if (!geometry || !geometry.attributes || !geometry.attributes.position) {
        return;
      }

      // Get group name
      const groupName = mesh.name || 'object';
      if (groupName !== this.currentGroup) {
        this.output += `\n# Group: ${groupName}\n`;
        this.output += `g ${groupName}\n`;
        this.currentGroup = groupName;
      }

      // Get vertices
      const positions = geometry.attributes.position;
      const positionArray = positions.array;

      // Get normals
      let normals = null;
      if (geometry.attributes.normal) {
        normals = geometry.attributes.normal;
      } else if (geometry.computeVertexNormals) {
        geometry.computeVertexNormals();
        normals = geometry.attributes.normal;
      }
      const normalArray = normals ? normals.array : null;

      // Write vertices
      for (let i = 0; i < positionArray.length; i += 3) {
        const vertex = new THREE.Vector3(
          positionArray[i],
          positionArray[i + 1],
          positionArray[i + 2]
        );

        // Transform vertex to world space
        const transformedVertex = this.transformVertex(vertex, worldMatrix);

        // Apply Blender rotation
        const blenderVertex = this.rotateForBlender(transformedVertex);

        this.output += `v ${blenderVertex.x.toFixed(6)} ${blenderVertex.y.toFixed(6)} ${blenderVertex.z.toFixed(6)}\n`;
      }

      // Write normals
      if (normalArray) {
        for (let i = 0; i < normalArray.length; i += 3) {
          const normal = new THREE.Vector3(
            normalArray[i],
            normalArray[i + 1],
            normalArray[i + 2]
          );

          // Transform normal
          const transformedNormal = this.transformNormal(normal, worldMatrix);

          // Apply Blender rotation
          const blenderNormal = this.rotateForBlender(transformedNormal);

          this.output += `vn ${blenderNormal.x.toFixed(6)} ${blenderNormal.y.toFixed(6)} ${blenderNormal.z.toFixed(6)}\n`;
        }
      }

      // Get indices
      let indices = null;
      if (geometry.index) {
        indices = geometry.index.array;
      } else {
        // Create sequential indices if none exist
        indices = new Array(positions.count);
        for (let i = 0; i < indices.length; i++) {
          indices[i] = i;
        }
      }

      // Write faces
      const useNormals = normalArray !== null;
      const faceSize = useNormals ? 3 : 2;

      for (let i = 0; i < indices.length; i += 3) {
        const i0 = vertexOffset + indices[i] + 1;
        const i1 = vertexOffset + indices[i + 1] + 1;
        const i2 = vertexOffset + indices[i + 2] + 1;

        if (useNormals) {
          const n0 = vertexOffset + indices[i] + 1;
          const n1 = vertexOffset + indices[i + 1] + 1;
          const n2 = vertexOffset + indices[i + 2] + 1;
          this.output += `f ${i0}//${n0} ${i1}//${n1} ${i2}//${n2}\n`;
        } else {
          this.output += `f ${i0} ${i1} ${i2}\n`;
        }
      }

      vertexOffset += positions.count;
    });

    return this.output;
  }
}

// Export the scene
const exporter = new OBJExporter();
const objString = exporter.exportObject(root);

// Add header
const header = `# OBJ file exported from Three.js
# Desk Globe Model
# Coordinate System: Blender Z-up (converted with -90° X-rotation)
# Original Three.js: Y-up
#

`;

// Create output directory if it doesn't exist
const outputDir = path.dirname('/root/output/object.obj');
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

// Write to file
fs.writeFileSync('/root/output/object.obj', header + objString);
console.log('OBJ file exported successfully to /root/output/object.obj');

